model Duty version "0.2" {
 type T=enum{yes,no}
 people[p]
 observed case{flag:bool=true}
 actor A{executors[p];capability check()->T{duration fixed 1min;result nondet{yes}}}
 process P{approved=A.check();end done}
 process Q{end done}
 cut K{include[A]}
 configuration Active{cut K;process P}
 configuration Hidden{cut K;process Q}
 responsible p for (approved == yes)
 bounds{cases 1;live_tasks 1;clock 3min}
 verify safety no_resource_overcommit
}

